// ----------------------------------------------------------------- the code

const KEYWORDS = new Set(
  'const let var function class new typeof instanceof in of this null undefined true false async void delete extends static get set interface type enum as'.split(' '),
)
const CONTROL = new Set('return if else for while do switch case break continue throw try catch finally import export from default await yield'.split(' '))
const TOKEN = /(\/\/.*)|(\/\*.*?(?:\*\/|$))|("(?:[^"\\]|\\.)*"?|'(?:[^'\\]|\\.)*'?|`(?:[^`\\]|\\.)*`?)|(\b\d[\d_]*(?:\.\d+)?\b)|([A-Za-z_$][\w$]*)|(\s+)|(.)/g

// One line as tokens [{t, k}], and whether a block comment is still open after it.
export function tokensOf(line, lang, inComment) {
  const out = []
  let at = 0
  if (inComment) {
    const end = line.indexOf('*/')
    if (end < 0) return { tokens: [{ t: line, k: 'm' }], open: true }
    out.push({ t: line.slice(0, end + 2), k: 'm' })
    at = end + 2
  }
  const json = lang === 'JSON'
  const plain = lang === 'Plain Text'
  let open = false
  TOKEN.lastIndex = at
  let m
  let prev = ''
  while (at < line.length && (m = TOKEN.exec(line))) {
    at = TOKEN.lastIndex
    const t = m[0]
    let k = 'p'
    if (plain) k = 'p'
    else if (m[1] && !json) k = 'm'
    else if (m[2] && !json) {
      k = 'm'
      open = !t.endsWith('*/') || t.length < 4
    } else if (m[3]) k = json && /^\s*:/.test(line.slice(at)) ? 'v' : 's'
    else if (m[4]) k = 'n'
    else if (m[5]) {
      if (json) k = KEYWORDS.has(t) ? 'k' : 'p'
      else if (CONTROL.has(t)) k = 'c'
      else if (KEYWORDS.has(t)) k = 'k'
      else if (prev === '<' || prev === '</') k = /^[A-Z]/.test(t) ? 't' : 'k'
      else if (/^\s*\(/.test(line.slice(at))) k = 'f'
      else if (/^[A-Z]/.test(t)) k = 't'
      else k = 'v'
    }
    if (!/^\s+$/.test(t)) prev = prev === '<' && t === '/' ? '</' : t
    const last = out[out.length - 1]
    if (last && last.k === k) last.t += t
    else out.push({ t, k })
  }
  return { tokens: out, open }
}

// ------------------------------------------------------------ the file open
//
// A file is one box that scrolls, as tall as all its lines, holding only the
// lines around where it is scrolled to (the screen showing and a screen above
// and below) as one <textarea>: colored by the spans inside it, typed into
// where it is tapped, its lines never wrapped (it scrolls sideways), the line
// numbers beside it. Spacers stand in for the lines above and below, and
// scrolling slides the window (onScroll). A window changes at one end at a
// time, so the field keeps its caret on the text it was in (docs/jsx-ui.md
// "Fields and the keyboard"), and a 2,000-line app is a hundred lines to lay
// out on an ESP32.

const ROW = 19 // VS Code's line height for 13 px
const PAD = 4 // above the first line

// The file open: its lines (the truth while it is typed into, folded back into
// the work's text when the window moves), the window [a, b) in the field, how
// many lines of the folded text the window stood for (`span`), whether it was
// typed into since (`dirty`), and the lines' tokens as far as they were read.
let current = null

// Where each file was scrolled to, by the work and the file.
let scrolls = null
const scrollsKept = () => scrolls || (scrolls = kept('scrolls', {}))

function docFor(work, file) {
  if (current && current.key === work.key && current.file === file) return current
  if (current && current.key === work.key) fold(work)
  const lines = String(work.files[file] || '').split('\n')
  current = { key: work.key, file, lines, a: -1, b: -1, span: 0, dirty: false, opens: [false], toks: [], ver: 0, rows: [], w: 0, wrap: true, rowsVer: 0 }
  return current
}

// What was typed, into the work's text (before the window moves, a save, an
// ask, another file).
function fold(work) {
  if (!current || !current.dirty || current.key !== work.key) return
  work.files[current.file] = current.lines.join('\n')
  if (!work.changed.includes(current.file)) work.changed.push(current.file)
  current.dirty = false
  setWork(work)
  frameos.remember('typing', null)
}

// The window for the line at the top of the screen and a screen of `fit`
// lines: a screen above it and below it. A window that does not reach that far
// grows at one end; one far longer than it shrinks at the other; one with
// nothing in common with it (a jump) is set anew.
function slide(work, doc, first, fit) {
  const n = doc.lines.length
  const want = [Math.max(0, first - fit), Math.min(n, first + 2 * fit + 1)]
  let { a, b } = doc
  if (a < 0 || b > n || want[1] <= a || want[0] >= b) [a, b] = want
  else if (want[0] < a) a = want[0]
  else if (want[1] > b) b = want[1]
  else if (b - a > 6 * fit) {
    if (first - a > b - first - fit) a = want[0]
    else b = want[1]
  }
  if (a === doc.a && b === doc.b) return
  fold(work)
  Object.assign(doc, { a, b, span: b - a })
  doc.ver++
}

// Line i's tokens, and whether a block comment is open at its start: read in
// order from the file's first line once, kept until an edit above them.
function tokensAt(doc, i, lang) {
  while (doc.opens.length <= i) {
    const j = doc.opens.length - 1
    const read = tokensOf(doc.lines[j], lang, doc.opens[j])
    doc.toks[j] = read.tokens
    doc.opens.push(read.open)
  }
  if (!doc.toks[i]) doc.toks[i] = tokensOf(doc.lines[i], lang, doc.opens[i]).tokens
  return doc.toks[i]
}

// What the field holds, colored: the tokens of the window's lines as spans
// (the rest as text), the same render after render until it changes.
function colored(doc, lang, look) {
  if (look.ink || !COLORED.has(lang)) return null
  if (doc.shown && doc.shown.ver === doc.ver) return doc.shown.nodes
  const nodes = []
  for (let i = doc.a; i < doc.b; i++) {
    for (const token of tokensAt(doc, i, lang)) {
      nodes.push(token.k === 'p' ? token.t : <span className={COLORS[token.k]}>{token.t}</span>)
    }
    if (i < doc.b - 1) nodes.push('\n')
  }
  doc.shown = { ver: doc.ver, nodes }
  return nodes
}

// Wrapped lines (on unless the status bar's Wrap is off): how many rows each
// line takes is measured as the field would set it (frameos.measureText, the
// same typesetting) for the lines the window holds, and guessed from its
// length for the rest. Where a line starts is the rows above it, summed.
function wrapFor(doc, wrap, width, look) {
  if (doc.wrap === wrap && doc.w === width) return
  Object.assign(doc, { wrap, w: width, rows: [] })
  doc.rowsVer++
}
const rowsAt = (doc, i, look) =>
  doc.rows[i] || (doc.wrap ? Math.max(1, Math.ceil((doc.lines[i].length * look.size * 0.6) / doc.w)) : 1)

// Line i's first row from the top, for every line and the end: kept until a
// line is measured or typed.
function rowSums(doc, look) {
  if (doc.sums && doc.sumsVer === doc.rowsVer && doc.sums.length === doc.lines.length + 1) return doc.sums
  const sums = [0]
  for (let i = 0; i < doc.lines.length; i++) sums.push(sums[i] + rowsAt(doc, i, look))
  doc.sums = sums
  doc.sumsVer = doc.rowsVer
  return sums
}

// The line at row `row` (the last whose first row is at or above it).
function lineAtRow(sums, row) {
  let lo = 0
  let hi = sums.length - 2
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1
    if (sums[mid] <= row) lo = mid
    else hi = mid - 1
  }
  return Math.max(0, lo)
}

// The window's lines measured. What the lines between the window's top and
// the screen's grew or shrank by (a guess put right) comes back in rows, for
// the box to scroll by so the screen does not move.
function measure(doc, first, look) {
  if (!doc.wrap) return 0
  const need = []
  for (let i = doc.a; i < doc.b; i++) if (!doc.rows[i]) need.push(i)
  if (!need.length) return 0
  const was = need.map((i) => rowsAt(doc, i, look))
  const heights = frameos.measureText(need.map((i) => doc.lines[i]), {
    className: `${MONO} text-[${look.size}px] leading-[${ROW}px]`,
    width: doc.w,
  })
  let moved = 0
  need.forEach((i, k) => {
    doc.rows[i] = Math.max(1, Math.round((heights[k] || ROW) / ROW))
    if (i < first) moved += doc.rows[i] - was[k]
  })
  doc.rowsVer++
  return moved
}

// The field typed into: its lines in place of the window's. Only the lines
// the edit changed are measured again (and read for tokens from the first of
// them): the rest keep their rows, which the box was laid out with. Were they
// guessed again, the next measure would take guess and measure apart for a
// correction and scroll the box by it, on every key (a 400-line file on a
// small screen jumped at each change).
export function typed(work, doc, text) {
  const lines = String(text).split('\n')
  const span = doc.b - doc.a
  let head = 0
  while (head < span && head < lines.length && doc.lines[doc.a + head] === lines[head]) head++
  let tail = 0
  while (tail < span - head && tail < lines.length - head && doc.lines[doc.b - 1 - tail] === lines[lines.length - 1 - tail]) tail++
  const from = doc.a + head
  const now = lines.slice(head, lines.length - tail)
  doc.lines.splice(from, span - head - tail, ...now)
  doc.rows.splice(from, span - head - tail, ...new Array(now.length)) // measured again
  doc.b = doc.a + lines.length
  doc.opens.length = Math.min(doc.opens.length, from + 1)
  doc.toks.length = Math.min(doc.toks.length, from)
  doc.rowsVer++
  doc.dirty = true
  doc.ver++
  frameos.remember('typing', { key: doc.key, file: doc.file, a: doc.a, span: doc.span, value: String(text) })
  if (!work.changed.includes(doc.file)) {
    work.changed.push(doc.file)
    setWork(work)
  }
}

