// Nothing open: the frame's scenes, and a start for a new one.
function Home({ app, look, spot, facts, asking }) {
  const openScene = (id) => {
    set(spot, { view: 'code', id, draft: false, folder: null, file: 'scene.json', note: '' })
    dropWork()
  }
  // The scenes need the frame page; without it, why not, where they would be.
  const scenes = facts.none ? (
    <span className={`p-[12px] text-[13px] leading-snug ${look.c.dim}`}>{facts.none}</span>
  ) : (
    <SceneList app={app} look={look} spot={spot} onOpen={openScene} />
  )
  const link = (d, text, onClick) => (
    <div className={`flex items-center gap-[6px] text-[13px] ${look.c.link}`} onClick={onClick}>
      <Icon d={d} size={14} stroke={d !== AI_ICON} />
      <span className="min-w-0 truncate">{text}</span>
    </div>
  )
  const recent = (Array.isArray(spot.recent) ? spot.recent : []).filter((f) => f && typeof f.storage === 'string').slice(0, look.wide ? 5 : 3)
  const welcome = (
    <div className={`flex flex-col flex-1 min-w-0 min-h-0 gap-[6px] p-[${look.wide ? 40 : 16}px] ${look.c.editor}`}>
      <span className="text-[26px] font-light">Code editor</span>
      <span className={`text-[14px] ${look.c.dim}`}>The code of this frame's scenes, and the files in its folders</span>
      <span className="pt-[18px] text-[15px]">Start</span>
      {facts.ask ? (
        link(AI_ICON, 'New scene with AI', () => set(spot, { view: 'ask', id: '', draft: false, folder: null, note: '' }))
      ) : facts.none ? null : (
        <span className={`text-[13px] ${look.c.dim}`}>A frame with a control plane can ask its AI for scenes.</span>
      )}
      {link(FOLDER_ICON, 'Open folder…', () => pickFolder(spot))}
      {recent.length ? <span className="pt-[14px] text-[15px]">Recent</span> : null}
      {recent.map((folder) => link(FOLDER_ICON, folderPath(app, folder), () => openFolder(spot, folder)))}
      {look.wide && facts.none ? null : <span className="pt-[14px] text-[15px]">Open</span>}
      {look.wide ? (
        facts.none ? null : (
          <span className={`text-[13px] leading-snug ${look.c.dim}`}>Pick a scene in the explorer to read its files and change them.</span>
        )
      ) : (
        scenes
      )}
    </div>
  )
  const list = Array.isArray(app.frame.scenes) ? app.frame.scenes : []
  return (
    <div className="flex flex-col flex-1 min-h-0">
      <div className="flex flex-1 min-h-0">
      {look.wide ? <ActivityBar look={look} spot={spot} facts={facts} open={!!spot.folder} /> : null}
      {look.wide ? (
        <div className={`shrink-0 flex flex-col w-[${look.sideW}px] min-h-0 ${look.c.side}`}>
          <SideHead look={look} text="SCENES" />
          {scenes}
        </div>
      ) : null}
      {asking ? <Ask look={look} spot={spot} facts={facts} work={null} /> : welcome}
      </div>
      <StatusBar look={look} left={[`${list.length} scene${list.length === 1 ? '' : 's'}`]} right={[facts.busy === 'ask' ? 'Asking the AI…' : facts.previewOnly ? 'Read only in the preview' : '']} />
    </div>
  )
}

// The request to the AI: a new scene, or a change to the one open.
function Ask({ look, spot, facts, work }) {
  const prompt = kept('prompt', '')
  const busy = facts.busy === 'ask'
  const changing = !!(spot.id || spot.draft)
  const send = () => {
    const text = kept('prompt', '').trim()
    if (!text) return set(spot, { note: say('empty_prompt') })
    const args = { prompt: text }
    if (changing && work && !work.error) {
      fold(work)
      const built = sceneOf(work.original, work.files)
      if (built.error) return set(spot, { note: built.error })
      args.scene = built.scene
    }
    const r = code('ask', args)
    set(spot, r.ok ? { asking: true, note: '' } : { note: r.why })
  }
  return (
    <div className={`flex flex-col flex-1 min-w-0 min-h-0 gap-[10px] p-[16px] ${look.c.editor}`}>
      {busy ? <div className={`shrink-0 h-[2px] ${look.ink ? 'bg-black' : 'bg-[#0e70c0]'}`} /> : null}
      <span className={`text-[11px] font-bold ${look.c.sideHead}`}>{changing ? 'ASK AI FOR A CHANGE' : 'ASK AI FOR A NEW SCENE'}</span>
      <span className={`text-[13px] leading-snug ${look.c.dim}`}>
        {changing
          ? 'What should change? The AI changes the scene as it is here, your unsaved edits included, and nothing is saved until you save its draft.'
          : 'What should the new scene show or do? Nothing is installed until you save the draft.'}
      </span>
      <textarea
        className={`flex-1 min-h-0 p-[8px] text-[13px] ${look.c.field}`}
        value={prompt}
        placeholder={changing ? 'Make the text bigger and add the date' : 'A clock with the weather in Brussels'}
        onChange={(e) => frameos.remember('prompt', String(e.target.value).slice(0, 2000))}
      />
      <div className="shrink-0 flex items-center gap-[8px]">
        <Button look={look} label={busy ? 'Asking…' : 'Ask'} primary off={busy} onClick={send} />
        <Button look={look} label="Cancel" off={busy} onClick={() => set(spot, { view: changing ? 'code' : 'list', note: '' })} />
        {busy ? <span className={`text-[12px] ${look.c.dim}`}>The AI is writing the scene and checking that it renders: a minute or two.</span> : null}
      </div>
    </div>
  )
}

// The file showing: the box that scrolls through all of it, its window of
// lines in a field beside their numbers. Where it is scrolled to is kept per
// file, and the box is told so (scrollTop) when another file opens.
function Editor({ look, spot, work, file, area }) {
  const doc = docFor(work, file)
  const lang = kindOf(file).lang
  const n = doc.lines.length
  const at = `${work.key}\u0000${file}`
  const wrap = spot.wrap !== false
  const gutterW = Math.round(look.size * 0.6 * Math.max(3, String(n).length) + 26)
  const textW = Math.max(40, area.width - gutterW - 10) // the scroll bar's room on the right
  let top = scrollsKept()[at] || 0
  if (doc.wrap !== wrap || doc.w !== textW) {
    // Wrap turned on or off, or another width: the same line stays at the top.
    const line = doc.w ? lineAtRow(rowSums(doc, look), Math.max(0, (top - PAD) / ROW)) : -1
    wrapFor(doc, wrap, textW, look)
    if (line >= 0) {
      top = PAD + rowSums(doc, look)[line] * ROW
      scrollsKept()[at] = top
      frameos.remember('scrolls', scrolls)
    }
  }
  const fit = Math.max(3, Math.ceil(area.height / ROW))
  let first = lineAtRow(rowSums(doc, look), Math.max(0, (top - PAD) / ROW))
  slide(work, doc, first, fit)
  const moved = measure(doc, first, look)
  if (moved) {
    // Lines above the screen were taller (or shorter) than guessed: the box
    // scrolls by as much, and what shows stays where it was.
    top = Math.max(0, top + moved * ROW)
    scrollsKept()[at] = top
    frameos.remember('scrolls', scrolls)
  }
  const sums = rowSums(doc, look)
  first = lineAtRow(sums, Math.max(0, (top - PAD) / ROW))
  const numbers = []
  for (let i = doc.a; i < doc.b; i++) {
    // The number by the line's first row, and nothing by the rows it wraps to.
    numbers.push(String(i + 1))
    for (let r = rowsAt(doc, i, look); r > 0; r--) if (i < doc.b - 1 || r > 1) numbers.push(<br />)
  }
  const last = lineAtRow(sums, (top - PAD + area.height) / ROW)
  const info = { lang, from: first, to: Math.min(n, last + 1), lines: n }
  const scrolled = (e) => {
    scrollsKept()[at] = e.scrollTop
    frameos.remember('scrolls', scrolls)
  }
  return {
    info,
    body: (
      <div
        className={`flex flex-col flex-1 min-h-0 overflow-y-auto ${MONO} text-[${look.size}px] ${look.c.editor}`}
        scrollTop={top}
        onScroll={scrolled}
      >
        <div className={`shrink-0 h-[${PAD + sums[doc.a] * ROW}px]`} />
        <div className="shrink-0 flex">
          <div className={`shrink-0 w-[${gutterW}px] pr-[18px] text-right whitespace-nowrap leading-[${ROW}px] ${look.c.gutter}`}>{numbers}</div>
          <textarea
            className={`${wrap ? `shrink-0 w-[${textW}px]` : 'flex-1 min-w-0 whitespace-nowrap overflow-x-auto'} leading-[${ROW}px] ${look.c.editor}`}
            value={doc.lines.slice(doc.a, doc.b).join('\n')}
            onChange={(e) => typed(work, doc, e.value)}
          >
            {colored(doc, lang, look)}
          </textarea>
        </div>
        <div className={`shrink-0 h-[${(sums[n] - sums[doc.b]) * ROW + 3 * ROW}px]`} />
      </div>
    ),
  }
}

// A scene (or the AI's draft) open: the workbench.
function Workbench({ app, look, spot, facts }) {
  const key = spot.draft ? DRAFT : spot.id
  const work = workFor(key)
  const busy = facts.busy
  const back = () => set(spot, { view: 'list', draft: false, note: '' })
  if (work.error) {
    return (
      <div className="flex flex-col flex-1 min-h-0">
        <div className={`flex flex-col flex-1 items-start gap-[12px] p-[16px] text-[13px] ${look.c.editor}`}>
          <span className={look.c.dim}>{work.error}</span>
          <Button look={look} label="Back to the scenes" onClick={back} />
        </div>
      </div>
    )
  }
  const file = work.order.includes(spot.file) ? spot.file : work.order[0]
  const changed = work.changed.length > 0
  const name = spot.draft ? (facts.draft && facts.draft.name) || 'New scene' : work.original.name || spot.id
  const summary = spot.draft && facts.draft ? facts.draft.summary : ''
  const asking = spot.view === 'ask' && facts.ask

  const save = (show) => {
    fold(work)
    const built = sceneOf(work.original, work.files)
    if (built.error) return set(spot, { note: built.error })
    const why = refusalOf(built.scene)
    if (why) return set(spot, { note: say(why) })
    // A scene new to the frame never takes its default from the owner.
    const known = (Array.isArray(app.frame.scenes) ? app.frame.scenes : []).some((s) => s && s.id === built.scene.id)
    if (!known) delete built.scene.default
    const r = code('save', { scene: built.scene, show })
    set(spot, r.ok ? { saving: { id: built.scene.id, show, draft: !!spot.draft }, note: '' } : { note: r.why })
  }
  const discard = () => {
    code('clear')
    dropWork()
    set(spot, { view: spot.id ? 'code' : 'list', draft: false, file: 'scene.json', note: '' })
  }

  // The room the code has: what the bars, the explorer and the AI's words leave.
  const sideW = look.wide ? look.activityW + look.sideW : 0
  const infoH = summary ? 38 : 0
  const area = {
    width: look.width - sideW,
    height: look.height - look.tabH - (look.wide ? 22 : 0) - look.statusH - infoH,
  }
  const editor = asking ? null : Editor({ look, spot, work, file, area })
  const info = editor ? editor.info : null

  const kind = kindOf(file)
  const tab = look.wide ? (
    <div className={`shrink-0 flex items-center gap-[6px] h-[${look.tabH}px] px-[12px] text-[13px] ${look.c.tab}`}>
      <span className={`text-[10px] font-bold ${look.ink ? '' : kind.color}`}>{kind.badge}</span>
      <span className="whitespace-nowrap">{file.slice(file.indexOf('/') + 1)}</span>
      <span className={look.c.dim}>{work.changed.includes(file) ? '•' : ''}</span>
    </div>
  ) : (
    <select
      className={`flex-1 min-w-0 h-[26px] px-[8px] text-[13px] ${look.c.field}`}
      value={file}
      onChange={(e) => set(spot, { file: String(e.target.value) })}
    >
      {work.order.map((f) => (
        <option value={f} className={f === file ? look.c.rowOn : ''}>
          {work.changed.includes(f) ? `${f} •` : f}
        </option>
      ))}
    </select>
  )
  // The tab, then what goes for the whole scene (Ask AI, a draft's Discard,
  // Save). A narrow screen has no activity bar: its way back to the scenes is
  // first.
  const tabBar = asking ? null : (
    <div className={`shrink-0 flex items-center gap-[6px] h-[${look.tabH}px] pr-[8px] ${look.c.tabs} ${look.wide ? '' : 'pl-[8px]'}`}>
      {look.wide ? null : <Button look={look} label="‹" onClick={back} />}
      {tab}
      <span className="flex-1" />
      {facts.ask ? <Button look={look} label="Ask AI" off={!!busy} onClick={() => set(spot, { view: 'ask', note: '' })} /> : null}
      {spot.draft ? <Button look={look} label="Discard" off={!!busy} onClick={discard} /> : null}
      {facts.save ? <Button look={look} label="Save" primary={changed || spot.draft} off={!!busy || (!changed && !spot.draft)} onClick={() => save(false)} /> : null}
      {facts.save && spot.draft ? <Button look={look} label="Save & show" off={!!busy} onClick={() => save(true)} /> : null}
    </div>
  )
  const crumbs = look.wide ? (
    <div className={`shrink-0 flex items-center h-[22px] px-[14px] text-[12px] whitespace-nowrap overflow-hidden ${look.c.crumbs}`}>
      {[name, ...file.split('/')].join('  ›  ')}
    </div>
  ) : null
  const aiSaid = summary ? (
    <div className={`shrink-0 flex items-center h-[${infoH}px] px-[12px] text-[12px] ${look.c.info}`}>
      <span className="truncate">{`AI: ${summary}`}</span>
    </div>
  ) : null

  return (
    <div className="flex flex-col flex-1 min-h-0">
      <div className="flex flex-1 min-h-0">
        {look.wide ? <ActivityBar look={look} spot={spot} facts={facts} open /> : null}
        {look.wide ? <Explorer look={look} spot={spot} work={work} file={file} title={name} /> : null}
        {asking ? (
          <Ask look={look} spot={spot} facts={facts} work={work} />
        ) : (
          <div className={`flex flex-col flex-1 min-w-0 min-h-0 ${look.c.editor}`}>
            {tabBar}
            {crumbs}
            {aiSaid}
            {editor.body}
          </div>
        )}
      </div>
      <StatusBar
        look={look}
        draft={spot.draft}
        left={[spot.draft ? 'AI draft' : spot.id, ...(changed ? [`${work.changed.length} changed`] : [])]}
        right={info ? codeInfo(spot, info) : [busy === 'ask' ? 'Asking the AI…' : '']}
      />
    </div>
  )
}

// ------------------------------------------------------ a folder, the pages

// Open folder: the frame's storages and their folders, walked into one at a
// time, and the folder showing opened as the work.
function FolderPicker({ app, look, spot, facts }) {
  const stores = storagesOf(app)
  const browse = spot.browse && typeof spot.browse === 'object' ? spot.browse : {}
  const storage = stores.some((s) => s.id === browse.storage) ? browse.storage : stores[0].id
  const path = storage === browse.storage && typeof browse.path === 'string' ? browse.path : ''
  const here = { storage, path }
  const entries = entriesIn(storage, path)
  const folders = entries.filter((e) => e.endsWith('/')).map((e) => e.replace(/\/$/, ''))
  const files = entries.length - folders.length
  const go = (to) => set(spot, { browse: { storage, path: to } })
  return (
    <div className="flex flex-col flex-1 min-h-0">
      <div className="flex flex-1 min-h-0">
        {look.wide ? <ActivityBar look={look} spot={spot} facts={facts} open={!!(spot.id || spot.draft || spot.folder)} /> : null}
        <div className={`flex flex-col flex-1 min-w-0 min-h-0 gap-[10px] p-[16px] ${look.c.editor}`}>
          <div className="shrink-0 flex items-center gap-[8px]">
            {look.wide ? null : <Button look={look} label="‹" onClick={() => set(spot, { view: spot.folder ? 'code' : 'list', note: '' })} />}
            <span className={`flex-1 text-[11px] font-bold ${look.c.sideHead}`}>OPEN FOLDER</span>
          </div>
          {stores.length > 1 ? (
            <div className="shrink-0 flex gap-[6px]">
              {stores.map((s) => (
                <Button look={look} label={s.name} primary={s.id === storage} onClick={() => set(spot, { browse: { storage: s.id, path: '' } })} />
              ))}
            </div>
          ) : null}
          <div className="shrink-0 flex items-center gap-[8px]">
            <Button look={look} label="Up" off={!path} onClick={() => go(parentOf(path))} />
            <span className="flex-1 min-w-0 truncate text-[13px]">{folderPath(app, here)}</span>
            <Button look={look} label="Open" primary onClick={() => openFolder(spot, here)} />
          </div>
          <div className={`flex flex-col flex-1 min-h-0 overflow-y-auto ${look.c.side}`}>
            {folders.map((f) => (
              <Row look={look} label={baseName(f)} closed icon={<Icon d={FOLDER_ICON} size={14} stroke />} onClick={() => go(f)} />
            ))}
            <span className={`p-[8px] text-[12px] ${look.c.dim}`}>
              {files ? `${files} file${files === 1 ? '' : 's'} in here too.` : folders.length ? '' : 'Nothing in here yet.'}
            </span>
          </div>
        </div>
      </div>
      <StatusBar look={look} left={[folderPath(app, here)]} right={[writable(here) ? '' : 'Read only']} />
    </div>
  )
}

// The name of a new file or folder, typed where it goes.
function Naming({ look, spot, work, open }) {
  const naming = spot.naming
  const dir = naming.dir || ''
  const cancel = () => {
    frameos.remember('naming', '')
    set(spot, { naming: null })
  }
  const done = () => {
    const made = create(work, naming.kind, dir, kept('naming', ''))
    if (made.error) return set(spot, { note: made.error })
    frameos.remember('naming', '')
    const expanded = dir && !open.includes(dir) ? [...open, dir] : open
    set(
      spot,
      naming.kind === 'folder'
        ? { naming: null, expanded: [...expanded, made.rel], at: made.rel, note: '' }
        : { naming: null, expanded, file: made.rel, note: '' },
    )
  }
  return (
    <div className="shrink-0 flex items-center gap-[4px] px-[8px] py-[3px]">
      <input
        className={`flex-1 min-w-0 h-[22px] px-[4px] text-[13px] ${look.c.field}`}
        value={kept('naming', '')}
        placeholder={`${naming.kind === 'folder' ? 'Folder' : 'File'} name${dir ? ' in ' + baseName(dir) : ''}`}
        onChange={(e) => frameos.remember('naming', String(e.target.value).slice(0, 120))}
        onKeyDown={(e) => {
          if (e.key === 'Enter') done()
          else if (e.key === 'Escape') cancel()
        }}
      />
      <Button look={look} label="Add" primary onClick={done} />
      <Button look={look} label="✕" onClick={cancel} />
    </div>
  )
}

// A folder's tree: its folders opened and closed in place, its files opened
// in the editor. New files and folders go into the folder last opened here.
function FolderExplorer({ look, spot, work, file, title, full = false }) {
  const { storage, path } = work.folder
  const open = Array.isArray(spot.expanded) ? spot.expanded.filter((d) => typeof d === 'string') : []
  const rows = folderRows(storage, path, open)
  const into = typeof spot.at === 'string' && (spot.at === '' || open.includes(spot.at)) ? spot.at : ''
  const toggle = (rel) =>
    set(spot, {
      at: rel,
      expanded: open.includes(rel) ? open.filter((d) => d !== rel && !d.startsWith(rel + '/')) : [...open, rel].slice(-40),
    })
  const close = () => {
    fold(work)
    // Unsaved files: said once, and let go on a second close.
    if (work.changed.length && !spot.closing) {
      const n = work.changed.length
      return set(spot, { closing: true, note: `${n} file${n === 1 ? ' is' : 's are'} not saved: Save, or close again to let ${n === 1 ? 'it' : 'them'} go.` })
    }
    closeFolder(spot)
  }
  const action = (d, onClick) => (
    <div className="shrink-0 flex items-center justify-center w-[22px] h-[22px]" onClick={onClick}>
      <Icon d={d} stroke size={16} />
    </div>
  )
  return (
    <div className={`${full ? 'flex-1 min-w-0' : `shrink-0 w-[${look.sideW}px]`} flex flex-col min-h-0 ${look.c.side}`}>
      <SideHead look={look} text="EXPLORER" />
      <div className={`shrink-0 flex items-center gap-[2px] h-[22px] pl-[8px] pr-[4px] text-[11px] font-bold ${look.c.sideHead}`}>
        <Icon d={OPEN} stroke size={14} />
        <span className="flex-1 min-w-0 truncate pl-[2px]">{String(title).toUpperCase()}</span>
        {writable(work.folder) ? action(NEW_FILE_ICON, () => set(spot, { naming: { kind: 'file', dir: into } })) : null}
        {writable(work.folder) ? action(NEW_FOLDER_ICON, () => set(spot, { naming: { kind: 'folder', dir: into } })) : null}
        {action(REFRESH_ICON, () => {
          forgetLists()
          set(spot, { note: '' })
        })}
        {action(CLOSE_ICON, close)}
      </div>
      {spot.naming ? <Naming look={look} spot={spot} work={work} open={open} /> : null}
      <div className="flex flex-col flex-1 min-h-0 overflow-y-auto">
        {rows.map((row) =>
          row.folder ? (
            <Row look={look} depth={row.depth + 1} label={row.name} chevron={row.open} closed={!row.open} on={row.rel === into && !!into} onClick={() => toggle(row.rel)} />
          ) : (
            <Row
              look={look}
              depth={row.depth + 1}
              on={row.rel === file}
              label={row.name}
              mark={work.changed.includes(row.rel) ? 'M' : ''}
              badge={kindOf(row.rel).badge}
              color={work.changed.includes(row.rel) ? look.c.changed : kindOf(row.rel).color}
              dim={!isTextName(row.rel)}
              onClick={() => set(spot, { file: row.rel, at: parentOf(row.rel), naming: null, note: '' })}
            />
          ),
        )}
        {rows.length ? null : <span className={`p-[12px] text-[13px] ${look.c.dim}`}>This folder is empty.</span>}
        {rows.length >= ROWS_MAX ? <span className={`p-[8px] text-[12px] ${look.c.dim}`}>More than fit here: close a folder.</span> : null}
      </div>
    </div>
  )
}

// A folder open: its tree and the file open, as a scene's are.
function FolderBench({ app, look, spot, facts }) {
  const work = workFor(folderKey(spot.folder))
  const title = folderTitle(app, work.folder)
  const file = typeof spot.file === 'string' ? spot.file : ''
  const problem = file ? loadFile(app, work, file) : ''
  const changed = work.changed.length
  const canWrite = writable(work.folder)
  const status = (right) => (
    <StatusBar
      look={look}
      left={[folderPath(app, work.folder), ...(changed ? [`${changed} changed`] : []), ...(canWrite ? [] : ['Read only'])]}
      right={right}
    />
  )
  // A narrow screen: the tree is the page until a file opens.
  if (!look.wide && !file) {
    return (
      <div className="flex flex-col flex-1 min-h-0">
        <div className="flex flex-1 min-h-0">
          <FolderExplorer look={look} spot={spot} work={work} file={file} title={title} full />
        </div>
        {status([])}
      </div>
    )
  }
  const sideW = look.wide ? look.activityW + look.sideW : 0
  const area = { width: look.width - sideW, height: look.height - look.tabH - (look.wide ? 22 : 0) - look.statusH }
  const editor = file && !problem ? Editor({ look, spot, work, file, area }) : null
  const kind = kindOf(file)
  const tabBar = (
    <div className={`shrink-0 flex items-center gap-[6px] h-[${look.tabH}px] pr-[8px] ${look.c.tabs} ${look.wide ? '' : 'pl-[8px]'}`}>
      {look.wide ? null : <Button look={look} label="‹" onClick={() => set(spot, { file: '', note: '' })} />}
      {file ? (
        <div className={`shrink-0 flex items-center gap-[6px] h-[${look.tabH}px] px-[12px] text-[13px] ${look.c.tab}`}>
          <span className={`text-[10px] font-bold ${look.ink ? '' : kind.color}`}>{kind.badge}</span>
          <span className="whitespace-nowrap">{baseName(file)}</span>
          <span className={look.c.dim}>{work.changed.includes(file) ? '•' : ''}</span>
        </div>
      ) : null}
      <span className="flex-1" />
      {canWrite ? (
        <Button look={look} label="Save" primary={changed > 0} off={!changed} onClick={() => set(spot, { closing: false, note: saveFolder(work) })} />
      ) : null}
    </div>
  )
  const crumbs =
    look.wide && file ? (
      <div className={`shrink-0 flex items-center h-[22px] px-[14px] text-[12px] whitespace-nowrap overflow-hidden ${look.c.crumbs}`}>
        {[title, ...file.split('/')].join('  ›  ')}
      </div>
    ) : null
  return (
    <div className="flex flex-col flex-1 min-h-0">
      <div className="flex flex-1 min-h-0">
        {look.wide ? <ActivityBar look={look} spot={spot} facts={facts} open /> : null}
        {look.wide ? <FolderExplorer look={look} spot={spot} work={work} file={file} title={title} /> : null}
        <div className={`flex flex-col flex-1 min-w-0 min-h-0 ${look.c.editor}`}>
          {tabBar}
          {crumbs}
          {editor ? (
            editor.body
          ) : (
            <div className={`flex flex-col flex-1 gap-[8px] p-[16px] text-[13px] ${look.c.editor}`}>
              <span className={look.c.dim}>{problem || 'Pick a file in the explorer to read it and change it.'}</span>
            </div>
          )}
        </div>
      </div>
      {status(editor ? codeInfo(spot, editor.info) : [])}
    </div>
  )
}

// The status bar's right side over a file: the lines showing, Wrap, the language.
function codeInfo(spot, info) {
  return [
    `Ln ${info.from + 1}–${info.to} of ${info.lines}`,
    // Wrap (VS Code's Alt+Z): long lines on rows of their own, or one row that scrolls sideways.
    <span className="shrink-0 whitespace-nowrap" onClick={() => set(spot, { wrap: spot.wrap === false })}>
      {spot.wrap === false ? 'No wrap' : 'Wrap'}
    </span>,
    info.lang,
  ]
}

// What came back since the last render: an answer from the AI, a save done.
function collect(spot, facts) {
  if (facts.busy) return
  if (spot.asking) {
    spot.asking = false
    if (facts.error) spot.note = say(facts.error)
    else if (facts.done === 'ask' && facts.draft) {
      dropWork()
      frameos.remember('prompt', '')
      set(spot, { view: 'code', draft: true, folder: null, file: 'scene.json', note: '' })
    }
  }
  if (spot.saving) {
    const saving = spot.saving
    spot.saving = null
    if (facts.error) spot.note = say(facts.error)
    else if (facts.done === 'save') {
      spot.note = saving.show ? 'Saved. The frame shows it once it arrives.' : 'Saved. The frame gets it with its next push.'
      if (saving.draft) {
        code('clear')
        set(spot, { draft: false, id: saving.id })
      }
      // Read again from what the frame holds, once the push lands.
      dropWork(true)
    }
  }
}

function getInRoom(app, context) {
  const look = lookOf(app, context)
  const spot = readSpot(app)
  opened(app, spot)
  const read = code('read')
  // Without the frame page there are no scenes to read: the folders still
  // open (they are the asset calls'), and the page says why the scenes do not.
  const facts =
    read.ok && read.value
      ? read.value
      : {
          none: read.ok
            ? "The scenes need the frame's settings on its screen, and this frame has them off (or no host to read scenes from)."
            : read.why,
          busy: '',
          ask: false,
          save: false,
        }
  if (!facts.none) {
    collect(spot, facts)
    if (facts.previewOnly && !spot.previewNoted) {
      spot.previewNoted = true
      spot.note = 'In the preview the code is read only: saving and the AI are on a frame.'
    }
  }
  const open = !facts.none && (spot.id || spot.draft)
  const asking = spot.view === 'ask' && facts.ask && !spot.folder
  let page
  if (spot.view === 'folders') page = <FolderPicker app={app} look={look} spot={spot} facts={facts} />
  else if (spot.folder && spot.view === 'code') page = <FolderBench app={app} look={look} spot={spot} facts={facts} />
  else if (open && (spot.view === 'code' || asking)) page = <Workbench app={app} look={look} spot={spot} facts={facts} />
  else page = <Home app={app} look={look} spot={spot} facts={facts} asking={asking} />
  saveSpot(spot)
  return (
    <div className={`relative flex flex-col w-full h-full text-[${look.size}px] ${look.c.editor}`}>
      {page}
      <Toast look={look} spot={spot} />
    </div>
  )
}

// A round panel (app.frame.round) shows only the circle inside its square.
// Drawn on the whole panel, the app lays out in the square inside that circle
// and is drawn there; in a window or a layout's hole its room is its own.
function roundRoom(app, context) {
  if (app.frame.round !== true) return null
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const panelWidth = (turned ? app.frame.height : app.frame.width) || 0
  const panelHeight = (turned ? app.frame.width : app.frame.height) || 0
  if (context && context.imageWidth && (Math.abs(context.imageWidth - panelWidth) > 2 || Math.abs(context.imageHeight - panelHeight) > 2)) {
    return null
  }
  const side = Math.floor((Math.min(panelWidth, panelHeight) / 2 - 12) * Math.SQRT2)
  return {
    width: panelWidth,
    height: panelHeight,
    side,
    x: Math.floor((panelWidth - side) / 2),
    y: Math.floor((panelHeight - side) / 2),
  }
}

export function get(app, context) {
  const ui = getInRoom(app, context)
  const room = roundRoom(app, context)
  if (!room || !ui || typeof ui !== 'object') return ui
  return (
    <div className={`relative w-[${room.width}px] h-[${room.height}px]`}>
      <div className={`absolute left-[${room.x}px] top-[${room.y}px] w-[${room.side}px] h-[${room.side}px]`}>{ui}</div>
    </div>
  )
}

